// Exports one roster run to versioned JSON report files. See docs/DESIGN.md §"Data model".
// Every file is written as { schemaVersion, generatedAt, data }, so a reader can tell which shape it
// is looking at without guessing from the contents. Writes are atomic: a temp file next to the target
// is renamed over it, so a reader never sees a half-written report and no temp file survives a run.
import { mkdir, readdir, rename, unlink, writeFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { dirname, join } from "node:path";

/** Version of the `{ schemaVersion, generatedAt, data }` envelope written by exportRun. */
export const SCHEMA_VERSION = 1;

/** A run as the coordinator holds it: a review, plus the plan, replays and gate decisions when there are any. */
export interface RunExport {
  review: unknown;
  plan?: unknown;
  replays?: unknown[];
  gate?: unknown[];
}

/** The envelope every report file shares. */
export interface ReportFile {
  schemaVersion: number;
  generatedAt: string;
  data: unknown;
}

/** File name per run section, in the order the sections appear in a run. */
const FILE_NAMES = ["review.json", "plan.json", "replays.json", "gate.json"] as const;

/** Keys of RunExport that become their own file: review.json is always written, the rest only when set. */
const OPTIONAL_KEYS = ["plan", "replays", "gate"] as const;

/**
 * Serializes one report file. Kept as JSON text with a trailing newline: the reports directory is
 * committed and read by scripts, so a diffable file beats a compact one.
 */
function render(file: ReportFile): string {
  return JSON.stringify(file, null, 2) + "\n";
}

/**
 * Writes review.json always, and plan.json, replays.json and gate.json when the run carries them
 * (`plan`, `replays` and `gate` are absent only when undefined; an empty object or array still gets
 * a file). Each file is the envelope `{ schemaVersion: 1, generatedAt, data }`. `outDir` is created
 * when missing. Returns the written paths, sorted.
 *
 * Re-export overwrites the files it writes; with identical data, generatedAt is the only field that
 * changes. Files the run does not ask for are left untouched, so an export never deletes unrelated
 * content of `outDir`.
 */
export async function exportRun(run: RunExport, outDir: string): Promise<string[]> {
  if (run === null || typeof run !== "object") throw new Error("exportRun: run must be an object");
  if (run.review === undefined) throw new Error("exportRun: run.review is required; review.json is always written");

  // All data is serialized before the first write, so data that cannot be encoded as JSON (a circular
  // reference, a BigInt, a throwing toJSON) fails the export without leaving any file behind.
  const generatedAt = new Date().toISOString();
  const present = (key: (typeof OPTIONAL_KEYS)[number]) => run[key] !== undefined;
  const files = FILE_NAMES.map((fileName) => {
    const data = keyFor(fileName) === "review" ? run.review : run[keyFor(fileName) as "plan" | "replays" | "gate"];
    return { fileName, body: render({ schemaVersion: SCHEMA_VERSION, generatedAt, data }) };
  }).filter(({ fileName }) => keyFor(fileName) === "review" || present(keyFor(fileName) as "plan" | "replays" | "gate"));

  await mkdir(outDir, { recursive: true });

  const paths: string[] = [];
  for (const { fileName, body } of files) {
    const path = join(outDir, fileName);
    await writeAtomic(path, body);
    paths.push(path);
  }
  return paths.sort();
}

/** "review.json" -> "review". */
function keyFor(fileName: string): string {
  return fileName.replace(/\.json$/, "");
}

/** Writes `body` to a unique temp file next to `path`, then renames it over `path`. */
async function writeAtomic(path: string, body: string): Promise<void> {
  const tmp = join(dirname(path), `.${randomUUID()}.tmp`);
  try {
    await writeFile(tmp, body);
    await rename(tmp, path);
  } catch (err) {
    // The rename either happened (and the temp file is gone) or it did not; only clean up a temp file we own.
    if (await exists(tmp)) await unlink(tmp).catch(() => {});
    throw err;
  }
}

async function exists(path: string): Promise<boolean> {
  try {
    await readdir(dirname(path));
  } catch {
    return false;
  }
  return (await readdir(dirname(path))).includes(path.slice(dirname(path).length + 1));
}

